begin;

-- Harden invitation credentials before exposing an acceptance RPC. Tokens are
-- generated by a trusted service with at least 256 bits of entropy; only their
-- lowercase SHA-256 digest is stored.
alter table public.partner_invitations
  drop constraint partner_invitations_token_hash_check,
  add constraint partner_invitations_token_hash_check
    check (token_hash ~ '^[0-9a-f]{64}$');

create unique index partner_invitations_token_hash_key
  on public.partner_invitations(token_hash);

create or replace function app_private.has_pregnancy_permission(
  target_pregnancy_id uuid,
  required_permission text
)
returns boolean
language sql
stable
security definer
set search_path = ''
set row_security = off
as $function$
  select auth.uid() is not null
    and (
      exists (
        select 1
        from public.pregnancies pregnancy
        where pregnancy.id = target_pregnancy_id
          and pregnancy.owner_id = auth.uid()
      )
      or exists (
        select 1
        from public.sharing_grants grant_row
        where grant_row.pregnancy_id = target_pregnancy_id
          and grant_row.grantee_user_id = auth.uid()
          and grant_row.permission = required_permission
          and grant_row.revoked_at is null
          and (
            grant_row.expires_at is null
            or grant_row.expires_at > pg_catalog.now()
          )
      )
    );
$function$;

comment on function app_private.has_pregnancy_permission(uuid, text) is
  'Returns ownership or one active, unexpired, explicitly named pregnancy capability.';

create or replace function app_private.can_read_journal_entry(target_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
set row_security = off
as $function$
  select exists (
    select 1 from public.journal_entries entry
    where entry.id = target_id
      and app_private.has_pregnancy_permission(entry.pregnancy_id, 'journal.read')
  );
$function$;

