create or replace function app_private.can_read_storage_object(
  target_bucket_id text,
  target_name text
)
returns boolean
language sql
stable
security definer
set search_path = ''
set row_security = off
as $function$
  select case target_bucket_id
    when 'tender-media' then exists (
      select 1 from public.media_assets asset
      where asset.storage_bucket = target_bucket_id
        and asset.storage_path = target_name
        and app_private.has_pregnancy_permission(asset.pregnancy_id, 'journal.read')
    )
    when 'tender-documents' then exists (
      select 1 from public.documents document
      where document.storage_bucket = target_bucket_id
        and document.storage_path = target_name
        and app_private.has_pregnancy_permission(document.pregnancy_id, 'care.read')
    )
    else false
  end;
$function$;

create or replace function app_private.can_manage_storage_object(
  target_bucket_id text,
  target_name text
)
returns boolean
language sql
stable
security definer
set search_path = ''
set row_security = off
as $function$
  select auth.uid() is not null and case target_bucket_id
    when 'tender-media' then exists (
      select 1 from public.media_assets asset
      where asset.storage_bucket = target_bucket_id
        and asset.storage_path = target_name
        and asset.owner_id = auth.uid()
    )
    when 'tender-documents' then exists (
      select 1 from public.documents document
      where document.storage_bucket = target_bucket_id
        and document.storage_path = target_name
        and document.owner_id = auth.uid()
    )
    else false
  end;
$function$;

-- Audit rows remain immutable to application writes. The sole exception is a
-- referential action that nulls a deleted actor/subject/pregnancy reference;
-- event content and immutable timestamps cannot change.
create or replace function app_private.prevent_record_mutation()
returns trigger
language plpgsql
volatile
security invoker
set search_path = ''
as $function$
begin
  if tg_table_schema = 'public'
    and tg_table_name = 'access_audit_events'
    and tg_op = 'UPDATE'
    and pg_catalog.pg_trigger_depth() > 1
    and new.id = old.id
    and new.event_type = old.event_type
    and new.resource_type = old.resource_type
    and new.resource_id is not distinct from old.resource_id
    and new.occurred_at = old.occurred_at
    and new.request_id is not distinct from old.request_id
    and new.ip_hash is not distinct from old.ip_hash
    and new.metadata = old.metadata
    and new.created_at = old.created_at
    and new.updated_at = old.updated_at
    and (new.actor_user_id is not distinct from old.actor_user_id or new.actor_user_id is null)
    and (new.subject_user_id is not distinct from old.subject_user_id or new.subject_user_id is null)
    and (new.pregnancy_id is not distinct from old.pregnancy_id or new.pregnancy_id is null)
    and (
      (old.actor_user_id is not null and new.actor_user_id is null)
      or (old.subject_user_id is not null and new.subject_user_id is null)
      or (old.pregnancy_id is not null and new.pregnancy_id is null)
    ) then
    return new;
  end if;

  raise exception 'record is append-only' using errcode = '55000';
end;
$function$;

do $migration$
declare
  function_signature text;
begin
  foreach function_signature in array array[
    'app_private.has_pregnancy_permission(uuid,text)',
    'app_private.can_read_journal_entry(uuid)',
    'app_private.can_read_tag(uuid)',
    'app_private.can_read_checkin(uuid)',
    'app_private.can_read_meal(uuid)',
    'app_private.can_read_appointment(uuid)',
    'app_private.can_read_medication(uuid)',
    'app_private.can_read_project(uuid)',
    'app_private.can_read_storage_object(text,text)',
    'app_private.can_manage_storage_object(text,text)'
  ] loop
    execute format('revoke all on function %s from public', function_signature);
    execute format('revoke all on function %s from anon', function_signature);
    execute format('revoke all on function %s from authenticated', function_signature);
    execute format('grant execute on function %s to authenticated', function_signature);
  end loop;
end;
$migration$;

create or replace function public.accept_partner_invitation(raw_token text)
returns uuid
language plpgsql
volatile
security definer
set search_path = ''
set row_security = off
as $function$
declare
  invitation public.partner_invitations%rowtype;
  actor_id uuid := auth.uid();
  actor_email text;
begin
  if actor_id is null or raw_token is null
    or pg_catalog.octet_length(raw_token) < 32
    or pg_catalog.octet_length(raw_token) > 512 then
    raise exception 'invitation is invalid or expired' using errcode = '22023';
  end if;

  select pg_catalog.lower(pg_catalog.btrim(auth_user.email))
  into actor_email
  from auth.users auth_user
  where auth_user.id = actor_id;

  select invitation_row.*
  into invitation
  from public.partner_invitations invitation_row
  where invitation_row.token_hash = pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(raw_token, 'UTF8'), 'sha256'),
      'hex'
    )
    and invitation_row.status = 'pending'
    and invitation_row.expires_at > pg_catalog.now()
    and invitation_row.invited_email = actor_email
  for update;

  if not found then
    raise exception 'invitation is invalid or expired' using errcode = '22023';
  end if;

  update public.partner_invitations
  set status = 'accepted',
      accepted_at = pg_catalog.now(),
      accepted_by_user_id = actor_id,
      updated_at = pg_catalog.now()
  where id = invitation.id and status = 'pending';

  if not found then
    raise exception 'invitation is invalid or expired' using errcode = '22023';
  end if;

  insert into public.pregnancy_members (
    pregnancy_id,
    owner_id,
    user_id,
    membership_role,
    status,
    joined_at
  ) values (
    invitation.pregnancy_id,
    invitation.owner_id,
    actor_id,
    invitation.invitation_role,
    'active',
    pg_catalog.now()
  )
  on conflict (pregnancy_id, user_id) do update
  set membership_role = excluded.membership_role,
      status = 'active',
      joined_at = excluded.joined_at,
      left_at = null,
      updated_at = pg_catalog.now();

  return invitation.pregnancy_id;
end;
$function$;

comment on function public.accept_partner_invitation(text) is
  'Atomically consumes one unexpired, email-bound invitation. Membership does not create a sharing grant.';

revoke all on function public.accept_partner_invitation(text) from public;
revoke all on function public.accept_partner_invitation(text) from anon;
revoke all on function public.accept_partner_invitation(text) from authenticated;
revoke all on function public.accept_partner_invitation(text) from service_role;
grant execute on function public.accept_partner_invitation(text) to authenticated;

-- Replace all repository-defined public policies in one forward migration. Any
-- policy not recreated below becomes deny-by-default.
do $migration$
declare
  conflicting_policies text;
  policy_record record;
  table_record record;
begin
  select pg_catalog.string_agg(
    pg_catalog.format('%I.%I', tablename, policyname),
    ', ' order by tablename, policyname
  )
  into conflicting_policies
  from pg_catalog.pg_policies
  where schemaname = 'public'
    and policyname not in (
      'active_emotions_read',
      'active_symptoms_read',
      'appointment_notes_explicit_grant_read',
      'appointment_questions_explicit_grant_read',
      'appointments_explicit_grant_read',
      'approved_clinical_reviews_read',
      'checkin_emotions_explicit_grant_read',
      'checkin_symptoms_explicit_grant_read',
      'consent_records_owner_create',
      'consent_records_owner_read',
      'daily_checkins_explicit_grant_read',
      'deletion_jobs_owner_create',
      'deletion_jobs_owner_read',
      'documents_explicit_grant_read',
      'emergency_contacts_explicit_grant_read',
      'export_jobs_owner_create',
      'export_jobs_owner_read',
      'journal_entries_explicit_grant_read',
      'journal_entry_tags_explicit_grant_read',
      'meal_items_explicit_grant_read',
      'meals_explicit_grant_read',
      'media_assets_explicit_grant_read',
      'medication_schedules_explicit_grant_read',
      'medications_explicit_grant_read',
      'notification_devices_owner_access',
      'owner_access',
      'photo_series_explicit_grant_read',
      'pregnancies_explicit_grant_read',
      'pregnancy_members_explicit_grant_read',
      'pregnancy_members_owner_manage',
      'pregnancy_members_self_read',
      'pregnancy_weeks_read',
      'profiles_owner_access',
      'projects_explicit_grant_read',
      'providers_explicit_grant_read',
      'published_articles_read',
      'published_content_sources_read',
      'published_urgent_guidance_read',
      'published_version_sources_read',
      'published_versions_read',
      'sharing_grants_grantee_read',
      'sharing_grants_owner_manage',
      'support_requests_explicit_grant_read',
      'tags_explicit_grant_read',
      'tasks_explicit_grant_read',
      'wellness_observations_explicit_grant_read'
    );

  if conflicting_policies is not null then
    raise exception
      'Refusing to replace unrecognized public RLS policies: %',
      conflicting_policies;
  end if;

  for table_record in
    select relation.oid, relation.relname
    from pg_catalog.pg_class relation
    join pg_catalog.pg_namespace namespace on namespace.oid = relation.relnamespace
    where namespace.nspname = 'public' and relation.relkind = 'r'
  loop
    execute format('alter table public.%I enable row level security', table_record.relname);
    execute format('revoke all on table public.%I from anon', table_record.relname);
    execute format('revoke all on table public.%I from authenticated', table_record.relname);
    execute format(
      'grant select, insert, update, delete on table public.%I to service_role',
      table_record.relname
    );

    for policy_record in
      select policyname from pg_catalog.pg_policies
      where schemaname = 'public' and tablename = table_record.relname
    loop
      execute format(
        'drop policy %I on public.%I',
        policy_record.policyname,
        table_record.relname
      );
    end loop;
  end loop;
end;
$migration$;

