  for select to authenticated
  using (
    exists (
      select 1
      from public.content_versions version
      join public.content_articles article on article.id = version.article_id
      where version.id = content_version_sources.content_version_id
        and version.published_at is not null
        and article.status = 'published'
        and article.current_version_id = version.id
        and app_private.has_approved_clinical_review(version.id, null)
    )
  );
create policy content_sources_published_select on public.content_sources
  for select to authenticated
  using (
    exists (
      select 1
      from public.content_version_sources version_source
      join public.content_versions version on version.id = version_source.content_version_id
      join public.content_articles article on article.id = version.article_id
      where version_source.content_source_id = content_sources.id
        and version.published_at is not null
        and article.status = 'published'
        and article.current_version_id = version.id
        and app_private.has_approved_clinical_review(version.id, null)
    )
  );
create policy clinical_reviews_published_select on public.clinical_reviews
  for select to authenticated
  using (
    status = 'approved'
    and reviewed_at is not null
    and (valid_until is null or valid_until > pg_catalog.now())
    and (
      (
        content_version_id is not null
        and exists (
          select 1
          from public.content_versions version
          join public.content_articles article on article.id = version.article_id
          where version.id = clinical_reviews.content_version_id
            and article.status = 'published'
            and article.current_version_id = version.id
        )
      )
      or (
        urgent_guidance_id is not null
        and exists (
          select 1 from public.urgent_guidance guidance
          where guidance.id = clinical_reviews.urgent_guidance_id
            and guidance.status = 'published'
            and guidance.effective_at <= pg_catalog.now()
            and (guidance.expires_at is null or guidance.expires_at > pg_catalog.now())
        )
      )
    )
  );
create policy urgent_guidance_published_select on public.urgent_guidance
  for select to authenticated
  using (
    status = 'published'
    and effective_at <= pg_catalog.now()
    and (expires_at is null or expires_at > pg_catalog.now())
    and app_private.has_approved_clinical_review(null, id)
  );

-- access_audit_events, notification_devices, export_jobs, and deletion_jobs
-- deliberately receive no anon/authenticated privileges or policies. Trusted
-- services use the service_role path and should expose narrow RPC/Edge APIs.

-- Private buckets. The exports bucket has no client policy; delivery must use a
-- short-lived signed URL produced by a trusted service after reauthorization.
insert into storage.buckets (id, name, public, file_size_limit)
values
  ('tender-media', 'tender-media', false, 52428800),
  ('tender-documents', 'tender-documents', false, 52428800),
  ('tender-exports', 'tender-exports', false, 52428800)
on conflict (id) do update
set public = false,
    file_size_limit = excluded.file_size_limit;

-- Supabase owns storage.objects and already enforces RLS on it. Project
-- migrations may add scoped policies, but they must not alter or regrant the
-- platform-owned table itself.

do $migration$
declare
  conflicting_policies text;
begin
  select pg_catalog.string_agg(policyname, ', ' order by policyname)
  into conflicting_policies
  from pg_catalog.pg_policies
  where schemaname = 'storage'
    and tablename = 'objects'
    and policyname not like 'tender_%';

  if conflicting_policies is not null then
    raise exception
      'Refusing to replace existing storage.objects policies: %',
      conflicting_policies;
  end if;

  execute 'drop policy if exists tender_objects_select on storage.objects';
  execute 'drop policy if exists tender_objects_insert on storage.objects';
  execute 'drop policy if exists tender_objects_update on storage.objects';
  execute 'drop policy if exists tender_objects_delete on storage.objects';
end;
$migration$;

create policy tender_objects_select on storage.objects
  for select to authenticated
  using (app_private.can_read_storage_object(bucket_id, name));
create policy tender_objects_insert on storage.objects
  for insert to authenticated
  with check (app_private.can_manage_storage_object(bucket_id, name));
create policy tender_objects_update on storage.objects
  for update to authenticated
  using (app_private.can_manage_storage_object(bucket_id, name))
  with check (app_private.can_manage_storage_object(bucket_id, name));
create policy tender_objects_delete on storage.objects
  for delete to authenticated
  using (app_private.can_manage_storage_object(bucket_id, name));

commit;
